Below is a suggested minimal, hardened version of `app.js` that incorporates the fixes above:

```js
// app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Harden HTTP headers
app.use(helmet());

// Optional: force HTTPS (in production behind reverse proxy)
app.use((req, res, next) => {
  if (req.secure || process.env.NODE_ENV !== 'production') return next();
  res.redirect(`https://${req.headers.host}${req.originalUrl}`);
});

// CORS policy – adapt to your environment
app.use(cors({ origin: process.env.ALLOWED_ORIGINS?.split(',') || false }));

// Rate limiting
const limiter = rateLimit({ windowMs: 15*60*1000, max: 100 });
app.use(limiter);

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Dummy executor – replace with DB or secure data store
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 404 handler
app.use((req, res) => res.status(404).json({ message: 'Not Found' }));

// Global error handler
app.use((err, req, res, next) => {
  console.error(err);                      // log (mask sensitive data)
  res.status(500).json({ message: 'Internal Server Error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

